    64  RawImage OrfDecoder::decodeRawInternal() {
    65    auto raw = mRootIFD->getIFDWithTag(STRIPOFFSETS);
    66
    67    int compression = raw->getEntry(COMPRESSION)->getU32();
    68    if (1 != compression)
    69      ThrowRDE("Unsupported compression");
    70
    71    TiffEntry *offsets = raw->getEntry(STRIPOFFSETS);
    72    TiffEntry *counts = raw->getEntry(STRIPBYTECOUNTS);
    73
    74    if (counts->count != offsets->count) {
    75      ThrowRDE(
    76          "Byte count number does not match strip size: count:%u, strips:%u ",
    77          counts->count, offsets->count);
    78    }
    79
    80    //TODO: this code assumes that all strips are layed out directly after another without padding and in order
    81    uint32 off = raw->getEntry(STRIPOFFSETS)->getU32();
    82    uint32 size = 0;
    83    for (uint32 i=0; i < counts->count; i++)
    84      size += counts->getU32(i);
    85
    86    if (!mFile->isValid(off, size))
    87      ThrowRDE("Truncated file");
    88
    89    uint32 width = raw->getEntry(IMAGEWIDTH)->getU32();
    90    uint32 height = raw->getEntry(IMAGELENGTH)->getU32();
    91
    92    mRaw->dim = iPoint2D(width, height);
    93    mRaw->createData();
    94
    95    ByteStream input(offsets->getRootIfdData());
    96    input.setPosition(off);
    97
    98    try {
    99      if (offsets->count != 1 || hints.has("force_uncompressed"))
   100        decodeUncompressed(input, width, height, size);
   101      else
   102        decodeCompressed(&input, width, height);
   103    } catch (IOException &e) {
   104       mRaw->setError(e.what());
   105    }
   106
   107    return mRaw;
   108  }
