   131  /* This is probably the slowest decoder of them all.
   132   * I cannot see any way to effectively speed up the prediction
   133   * phase, which is by far the slowest part of this algorithm.
   134   * Also there is no way to multithread this code, since prediction
   135   * is based on the output of all previous pixel (bar the first four)
   136   */
   137
   138  void OrfDecoder::decodeCompressed(ByteStream* s, uint32 w, uint32 h) {
   139    int nbits;
   140    int sign;
   141    int low;
   142    int high;
   143    int i;
   144    int left0;
   145    int nw0;
   146    int left1;
   147    int nw1;
   148    int acarry0[3];
   149    int acarry1[3];
   150    int pred;
   151    int diff;
   152
   153    uchar8* data = mRaw->getData();
   154    int pitch = mRaw->pitch;
   155
   156    /* Build a table to quickly look up "high" value */
   157    unique_ptr<char[]> bittable(new char[4096]);
   158
   159    for (i = 0; i < 4096; i++) {
   160      int b = i;
   161      for (high = 0; high < 12; high++)
   162        if ((b>>(11-high))&1)
   163          break;
   164      bittable[i] = min(12,high);
   165    }
   166    left0 = nw0 = left1 = nw1 = 0;
   167
   168    s->skipBytes(7);
   169    BitPumpMSB bits(*s);
   170
   171    for (uint32 y = 0; y < h; y++) {
   172      memset(acarry0, 0, sizeof acarry0);
   173      memset(acarry1, 0, sizeof acarry1);
   174      auto* dest = reinterpret_cast<ushort16*>(&data[y * pitch]);
   175      bool y_border = y < 2;
   176      bool border = true;
   177      for (uint32 x = 0; x < w; x++) {
   178        bits.fill();
   179        i = 2 * (acarry0[2] < 3);
   180        for (nbits = 2 + i; static_cast<ushort16>(acarry0[0]) >> (nbits + i);
   181             nbits++)
   182          ;
   183
   184        int b = bits.peekBitsNoFill(15);
   185        sign = (b >> 14) * -1;
   186        low  = (b >> 12) & 3;
   187        high = bittable[b&4095];
   188
   189        // Skip bytes used above or read bits
   190        if (high == 12) {
   191          bits.skipBitsNoFill(15);
   192          high = bits.getBits(16 - nbits) >> 1;
   193        } else {
   194          bits.skipBitsNoFill(high + 1 + 3);
   195        }
   196
   197        acarry0[0] = (high << nbits) | bits.getBits(nbits);
   198        diff = (acarry0[0] ^ sign) + acarry0[1];
   199        acarry0[1] = (diff * 3 + acarry0[1]) >> 5;
   200        acarry0[2] = acarry0[0] > 16 ? 0 : acarry0[2] + 1;
   201
   202        if (border) {
   203          if (y_border && x < 2)
   204            pred = 0;
   205          else {
   206            if (y_border)
   207              pred = left0;
   208            else {
   209              pred = dest[-pitch + (static_cast<int>(x))];
   210              nw0 = pred;
   211            }
   212          }
   213          dest[x] = pred + ((diff * 4) | low);
   214          // Set predictor
   215          left0 = dest[x];
   216        } else {
   217          // Have local variables for values used several tiles
   218          // (having a "ushort16 *dst_up" that caches dest[-pitch+((int)x)] is actually slower, probably stack spill or aliasing)
   219          int up = dest[-pitch + (static_cast<int>(x))];
   220          int leftMinusNw = left0 - nw0;
   221          int upMinusNw = up - nw0;
   222          // Check if sign is different, and they are both not zero
   223          if ((signbit(leftMinusNw) ^ signbit(upMinusNw)) &&
   224              (leftMinusNw != 0 && upMinusNw != 0)) {
   225            if (abs(leftMinusNw) > 32 || abs(upMinusNw) > 32)
   226              pred = left0 + upMinusNw;
   227            else
   228              pred = (left0 + up) >> 1;
   229          } else
   230            pred = abs(leftMinusNw) > abs(upMinusNw) ? left0 : up;
   231
   232          dest[x] = pred + ((diff * 4) | low);
   233          // Set predictors
   234          left0 = dest[x];
   235          nw0 = up;
   236        }
   237
   238        // ODD PIXELS
   239        x += 1;
   240        bits.fill();
   241        i = 2 * (acarry1[2] < 3);
   242        for (nbits = 2 + i; static_cast<ushort16>(acarry1[0]) >> (nbits + i);
   243             nbits++)
   244          ;
   245        b = bits.peekBitsNoFill(15);
   246        sign = (b >> 14) * -1;
   247        low  = (b >> 12) & 3;
   248        high = bittable[b&4095];
   249
   250        // Skip bytes used above or read bits
   251        if (high == 12) {
   252          bits.skipBitsNoFill(15);
   253          high = bits.getBits(16 - nbits) >> 1;
   254        } else {
   255          bits.skipBitsNoFill(high + 1 + 3);
   256        }
   257
   258        acarry1[0] = (high << nbits) | bits.getBits(nbits);
   259        diff = (acarry1[0] ^ sign) + acarry1[1];
   260        acarry1[1] = (diff * 3 + acarry1[1]) >> 5;
   261        acarry1[2] = acarry1[0] > 16 ? 0 : acarry1[2] + 1;
   262
   263        if (border) {
   264          if (y_border && x < 2)
   265            pred = 0;
   266          else {
   267            if (y_border)
   268              pred = left1;
   269            else {
   270              pred = dest[-pitch + (static_cast<int>(x))];
   271              nw1 = pred;
   272            }
   273          }
   274          dest[x] = left1 = pred + ((diff * 4) | low);
   275        } else {
   276          int up = dest[-pitch + (static_cast<int>(x))];
   277          int leftMinusNw = left1 - nw1;
   278          int upMinusNw = up - nw1;
   279
   280          // Check if sign is different, and they are both not zero
   281          if ((signbit(leftMinusNw) ^ signbit(upMinusNw)) &&
   282              (leftMinusNw != 0 && upMinusNw != 0)) {
   283            if (abs(leftMinusNw) > 32 || abs(upMinusNw) > 32)
   284              pred = left1 + upMinusNw;
   285            else
   286              pred = (left1 + up) >> 1;
   287          } else
   288            pred = abs(leftMinusNw) > abs(upMinusNw) ? left1 : up;
   289
   290          dest[x] = left1 = pred + ((diff * 4) | low);
   291          nw1 = up;
   292        }
   293        border = y_border;
   294      }
   295    }
   296  }
