    63  TiffRootIFDOwner TiffParser::parse(const Buffer& data) {
    64    ByteStream bs(data, 0);
    65    bs.setInNativeByteOrder(isTiffInNativeByteOrder(bs, 0, "TIFF header"));
    66    bs.skipBytes(2);
    67
    68    ushort16 magic = bs.getU16();
    69    if (magic != 42 && magic != 0x4f52 && magic != 0x5352 && magic != 0x55) // ORF has 0x4f52/0x5352, RW2 0x55 - Brillant!
    70      ThrowTPE("Not a TIFF file (magic 42)");
    71
    72    TiffRootIFDOwner root = make_unique<TiffRootIFD>(
    73        nullptr, bs,
    74        UINT32_MAX); // tell TiffIFD constructur not to parse bs as IFD
    75    for( uint32 nextIFD = bs.getU32(); nextIFD; nextIFD = root->getSubIFDs().back()->getNextIFD() ) {
    76      root->add(make_unique<TiffIFD>(root.get(), bs, nextIFD));
    77    }
    78
    79    return root;
    80  }
