   120          DECODER(RafDecoder), DECODER(NefDecoder), DECODER(OrfDecoder),
   121          DECODER(ArwDecoder), DECODER(PefDecoder), DECODER(Rw2Decoder),
   122          DECODER(SrwDecoder), DECODER(MefDecoder), DECODER(DcrDecoder),
   123          DECODER(DcsDecoder), DECODER(KdcDecoder), DECODER(ErfDecoder),
   124          DECODER(ThreefrDecoder),
   125
